(2224769, 305684, 43156, '<td valign="top">Nice presentation, excellent execution; 10</td>', 'Nice presentation, excellent execution; 10', '2006-03-13 14:13:45.000000', NULL, 1),
(2224781, 305170, 46648, '<td valign="top">i find the out-of-focus leaf in the front to be distracting</td>', 'i find the out-of-focus leaf in the front to be distracting', '2006-03-13 14:17:38.000000', NULL, 1),
(2224783, 305619, 43156, '<td valign="top">Nice presentation, excellent execution; 10</td>', 'Nice presentation, excellent execution; 10', '2006-03-13 14:18:14.000000', NULL, 1),
(2224786, 306011, 5391, '<td valign="top">Really interesting shot.  The composition is especially artful for what I assume was a "click or you''ll miss it" photograph.  Three things really give it a nice balance:  the lines of the tree and where they intersect with the line of the red bricks, the placement of the two faces, and the tiny bright green sprigs in the upper left.  You couldn''t have planned it better.  Lively colors and perfect exposure add to the exciting "feel" of the shot.  It may not do well if people don''t stop to really look at it in the voting process, but it''s really, really good.  10</td>', 'Really interesting shot.  The composition is especially artful for what I assume was a "click or you''ll miss it" photograph.  Three things really give it a nice balance:  the lines of the tree and where they intersect with the line of the red bricks, the placement of the two faces, and the tiny bright green sprigs in the upper left.  You couldn''t have planned it better.  Lively colors and perfect exposure add to the exciting "feel" of the shot.  It may not do well if people don''t stop to really look at it in the voting process, but it''s really, really good.  10', '2006-03-13 14:20:12.000000', NULL, 1),
(2224863, 305721, 35804, '<td valign="top">Fabulous...perfect light, color and motion.</td>', 'Fabulous...perfect light, color and motion.', '2006-03-13 15:11:14.000000', NULL, 1),
