INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2232774, 305781, 27133, '<td valign="top">Incredible!!</td>', 'Incredible!!', '2006-03-16 06:14:53.000000', NULL, 1),
(2232777, 303995, 25355, '<td valign="top">Funny how that incorrect quotation is so well-known. ;-)</td>', 'Funny how that incorrect quotation is so well-known. ;-)', '2006-03-16 06:15:59.000000', NULL, 1),
(2232779, 305456, 44611, '<td valign="top">Gross!  I can''t imagine the mindset that motivated you to use that particular line!</td>', 'Gross!  I can''t imagine the mindset that motivated you to use that particular line!', '2006-03-16 06:16:35.000000', NULL, 1),
(2232780, 305246, 25355, '<td valign="top">Ah, even the Grim Reaper is keeping up with the latest technology, I see. The red backdrop is brilliant.</td>', 'Ah, even the Grim Reaper is keeping up with the latest technology, I see. The red backdrop is brilliant.', '2006-03-16 06:17:45.000000', NULL, 1),
(2232781, 305619, 25355, '<td valign="top">Wonderful realisation, though perhaps they''re a wee bit underdressed for angels (even though cherubs are depicted as usually naked). Anyway, top ten finish for sure.</td>', 'Wonderful realisation, though perhaps they''re a wee bit underdressed for angels (even though cherubs are depicted as usually naked). Anyway, top ten finish for sure.', '2006-03-16 06:20:20.000000', NULL, 1),
(2232783, 306008, 25355, '<td valign="top">Trout Fishing in America by Richard Brautigan.</td>', 'Trout Fishing in America by Richard Brautigan.', '2006-03-16 06:21:48.000000', NULL, 1),
(2232785, 305085, 25355, '<td valign="top">You have to ride snowmobiles to get to heaven? ;-)<br/>Good control of exposure.</td>', 'You have to ride snowmobiles to get to heaven? ;-)Good control of exposure.', '2006-03-16 06:23:11.000000', NULL, 1),
(2232786, 305086, 44611, '<td valign="top">Now there''s a place that needs some TLC.  Looks like it could be quite a place with a bit of money spent on it.  I haven''t read the book, so can''t comment on the image as a representation of it but this image evokes neglect and desolation.</td>', 'Now there''s a place that needs some TLC.  Looks like it could be quite a place with a bit of money spent on it.  I haven''t read the book, so can''t comment on the image as a representation of it but this image evokes neglect and desolation.', '2006-03-16 06:23:53.000000', NULL, 1),
(2232790, 304250, 44611, '<td valign="top">The addition of a letter would have helped this composition, and perhaps placing the book more at an angle - it seems so straight and arranged.</td>', 'The addition of a letter would have helped this composition, and perhaps placing the book more at an angle - it seems so straight and arranged.', '2006-03-16 06:25:55.000000', NULL, 1),
(2232792, 304868, 25355, '<td valign="top">The thing about Pippi Longstocking, though, was that her stockings never matched in colour...</td>', 'The thing about Pippi Longstocking, though, was that her stockings never matched in colour...', '2006-03-16 06:26:47.000000', NULL, 1),
(2232793, 303919, 44611, '<td valign="top">Unfortunately, this seems rather unexciting although the detail is pretty amazing.</td>', 'Unfortunately, this seems rather unexciting although the detail is pretty amazing.', '2006-03-16 06:27:15.000000', NULL, 1),
(2232796, 306011, 44611, '<td valign="top">It''s a real shame that more of the dog isn''t included in this shot, the story it tells is fabulous and such a great choice for the book title.  Cloning out the leaves, top left, might have helped too as they are slightly distracting.  Great light and sharpness.</td>', 'It''s a real shame that more of the dog isn''t included in this shot, the story it tells is fabulous and such a great choice for the book title.  Cloning out the leaves, top left, might have helped too as they are slightly distracting.  Great light and sharpness.', '2006-03-16 06:31:35.000000', NULL, 1),
(2232812, 304802, 44611, '<td valign="top">Gosh - this looks like it might be someone''s home?  Great capture, but sad if it was.</td>', 'Gosh - this looks like it might be someone''s home?  Great capture, but sad if it was.', '2006-03-16 06:41:40.000000', NULL, 1),
(2232814, 305957, 44611, '<td valign="top">This is very beautiful and so tranquil.  One of my top 10 scores - Good luck.</td>', 'This is very beautiful and so tranquil.  One of my top 10 scores - Good luck.', '2006-03-16 06:43:00.000000', NULL, 1),
(2232818, 304045, 44611, '<td valign="top">Wow! That is beautiful.  A fantastic tiger portrait - detail, colour, composition all spot on.  Right up there in my top scores, good luck.</td>', 'Wow! That is beautiful.  A fantastic tiger portrait - detail, colour, composition all spot on.  Right up there in my top scores, good luck.', '2006-03-16 06:44:03.000000', NULL, 1),
(2232821, 305764, 44611, '<td valign="top">Lots of points for originality and humour!  A very clever interpretation and a good photo too.  One of my top 10 scores - good luck.</td>', 'Lots of points for originality and humour!  A very clever interpretation and a good photo too.  One of my top 10 scores - good luck.', '2006-03-16 06:44:49.000000', NULL, 1),
(2232824, 304596, 44611, '<td valign="top">This just oozes tranquility and so fits the book title.  Lovely colours and composition.  Good luck - amongst my top scoring images.</td>', 'This just oozes tranquility and so fits the book title.  Lovely colours and composition.  Good luck - amongst my top scoring images.', '2006-03-16 06:45:30.000000', NULL, 1),
(2232831, 305616, 44611, '<td valign="top">I love trees, but prefer them with leaves.  This is a great image though, I particularly like the curve of the grassy hill as it meets the horizon.  The sky is bit blurry - sharper would probably improve this shot as it would fit with the starkness of the winter tree.  One of my top scoring images - good luck.</td>', 'I love trees, but prefer them with leaves.  This is a great image though, I particularly like the curve of the grassy hill as it meets the horizon.  The sky is bit blurry - sharper would probably improve this shot as it would fit with the starkness of the winter tree.  One of my top scoring images - good luck.', '2006-03-16 06:47:23.000000', NULL, 1),
(2232837, 305026, 44611, '<td valign="top">The red lighting is very weird here and to be honest the composition of the shot is very poor.  The fact that the top and bottom of the book are cropped and shooting flat down at it makes it very one-dimensional.  Placing the book at more of an angle and shooting from a lower level would have improved this.</td>', 'The red lighting is very weird here and to be honest the composition of the shot is very poor.  The fact that the top and bottom of the book are cropped and shooting flat down at it makes it very one-dimensional.  Placing the book at more of an angle and shooting from a lower level would have improved this.', '2006-03-16 06:49:23.000000', NULL, 1),
(2232839, 305899, 44611, '<td valign="top">Very busy image, but with no clear subject.  Too many distractions.</td>', 'Very busy image, but with no clear subject.  Too many distractions.', '2006-03-16 06:50:06.000000', NULL, 1),
(2233097, 305619, 24846, '<td valign="top">Wow what a setup. Like composition, angles of the angels. May be to much shadows, not sure what to change though. The shadow between her left shoulder and his chest distracts me for some reason Good luck. -7-</td>', 'Wow what a setup. Like composition, angles of the angels. May be to much shadows, not sure what to change though. The shadow between her left shoulder and his chest distracts me for some reason Good luck. -7-', '2006-03-16 10:20:45.000000', NULL, 1),
(2233101, 305992, 24846, '<td valign="top">Neat idea, is this in Flagstaff region per chance? Like the crisp bright colors and perfect crop choice. Good luck with this captivating cactus image. -8-</td>', 'Neat idea, is this in Flagstaff region per chance? Like the crisp bright colors and perfect crop choice. Good luck with this captivating cactus image. -8-', '2006-03-16 10:24:25.000000', NULL, 1),
