(2236979, 304906, 259, '<td valign="top">very nice point of view.</td>', 'very nice point of view.', '2006-03-18 01:19:04.000000', NULL, 1),
(2236983, 305616, 259, '<td valign="top">this shot has a lot of potential.  i would predict that if the tree were on one of the thirds your picture would score at least a full point higher.  as it is now, the tree is slightly off-center; which creates an uneasy feeling.</td>', 'this shot has a lot of potential.  i would predict that if the tree were on one of the thirds your picture would score at least a full point higher.  as it is now, the tree is slightly off-center; which creates an uneasy feeling.', '2006-03-18 01:23:03.000000', NULL, 1),
(2236985, 305806, 259, '<td valign="top">i really like the tonal range.  the only thing i am undecided about is the horizontal pole, or whatever it is.  in some ways i think it works, but at the same time it seems to distract from the man, and his hands in particular.</td>', 'i really like the tonal range.  the only thing i am undecided about is the horizontal pole, or whatever it is.  in some ways i think it works, but at the same time it seems to distract from the man, and his hands in particular.', '2006-03-18 01:25:33.000000', NULL, 1),
(2236988, 304918, 259, '<td valign="top">i like the picture, but the border draws my eye away from the picture because there is too much going on with it.</td>', 'i like the picture, but the border draws my eye away from the picture because there is too much going on with it.', '2006-03-18 01:26:53.000000', NULL, 1),
