(2236996, 305026, 259, '<td valign="top">not very imaginative.</td>', 'not very imaginative.', '2006-03-18 01:34:04.000000', NULL, 1),
(2237001, 305170, 259, '<td valign="top">easily one the best.  the green on yellow is great, and the simplicity is what gives your shot the extra pop that others lack.  everyone should look at this picture and learn how less is more.</td>', 'easily one the best.  the green on yellow is great, and the simplicity is what gives your shot the extra pop that others lack.  everyone should look at this picture and learn how less is more.', '2006-03-18 01:37:21.000000', NULL, 1),
