(2237317, 305336, 44980, '<td valign="top">Very good idea. A bit of hand shaken though</td>', 'Very good idea. A bit of hand shaken though', '2006-03-18 10:17:09.000000', NULL, 1),
(2237371, 305302, 25218, '<td valign="top">clever idea, but I think using all of the same type of soup can would have made for a more pleasing image - like the chicken noodle soup, and then coverting the image to a soft sepia, to evoke the 1930''s.. boy, I''m just taking over your picture, huh? Anyway, that''s what I''m thinking.</td>', 'clever idea, but I think using all of the same type of soup can would have made for a more pleasing image - like the chicken noodle soup, and then coverting the image to a soft sepia, to evoke the 1930''s.. boy, I''m just taking over your picture, huh? Anyway, that''s what I''m thinking.', '2006-03-18 11:02:43.000000', NULL, 1),
(2237373, 305890, 25218, '<td valign="top">Beautiful lighting, and nice composition. You took a cliche and made it interesting - great job!</td>', 'Beautiful lighting, and nice composition. You took a cliche and made it interesting - great job!', '2006-03-18 11:05:31.000000', NULL, 1),
(2237378, 304109, 9690, '<td valign="top">I think the yellow border is distracting.  It pulls your eyes away from the focal point in the middle of the pic.  The lighting is fading off into nothing, and you disrupt it with the border.</td>', 'I think the yellow border is distracting.  It pulls your eyes away from the focal point in the middle of the pic.  The lighting is fading off into nothing, and you disrupt it with the border.', '2006-03-18 11:11:07.000000', NULL, 1),
(2237380, 305721, 9690, '<td valign="top">I love the motion blur here.  The lighting and focal point is great.  Perfect!</td>', 'I love the motion blur here.  The lighting and focal point is great.  Perfect!', '2006-03-18 11:12:40.000000', NULL, 1),
(2237381, 304918, 9690, '<td valign="top">This looks really unbalanced to me.  The tracks are so heavy on the right side of the pic.</td>', 'This looks really unbalanced to me.  The tracks are so heavy on the right side of the pic.', '2006-03-18 11:13:19.000000', NULL, 1),
(2237383, 305997, 9690, '<td valign="top">Great use of vectors to create depth.  Great shot! 9</td>', 'Great use of vectors to create depth.  Great shot! 9', '2006-03-18 11:16:02.000000', NULL, 1),
(2237447, 305956, 24846, '<td valign="top">Ah, young Holden Caulfield having a breakdown. Nice colors, tones. Looks like he might be sitting in the Edmont hotel lobby. Good luck -8-</td>', 'Ah, young Holden Caulfield having a breakdown. Nice colors, tones. Looks like he might be sitting in the Edmont hotel lobby. Good luck -8-', '2006-03-18 12:03:26.000000', NULL, 1),
