(2239961, 305877, 42005, '<td valign="top">The sun really is bright...just as it is often at sunset.  Great fucus.</td>', 'The sun really is bright...just as it is often at sunset.  Great fucus.', '2006-03-19 21:16:45.000000', NULL, 1),
(2239965, 304285, 42005, '<td valign="top">Quite appropriate for this day!  Intriguing angle.  Thanks for sharing.</td>', 'Quite appropriate for this day!  Intriguing angle.  Thanks for sharing.', '2006-03-19 21:17:11.000000', NULL, 1),
