(2240102, 305957, 30669, '<td valign="top">Magnificent -10</td>', 'Magnificent -10', '2006-03-19 22:17:08.000000', NULL, 1),
(2240105, 305346, 39057, '<td valign="top">How the H*ll did you think of this? Great concept and I don''t know how you could have made the shot better than it is. I feel that the concept should get you in to the top 20. However, most DPCers seem to ignore creativity if the shot is not PERFECT!   8 from me.</td>', 'How the H*ll did you think of this? Great concept and I don''t know how you could have made the shot better than it is. I feel that the concept should get you in to the top 20. However, most DPCers seem to ignore creativity if the shot is not PERFECT!   8 from me.', '2006-03-19 22:17:20.000000', NULL, 1),
(2240106, 305418, 30669, '<td valign="top">Love the lighting. magnificent!</td>', 'Love the lighting. magnificent!', '2006-03-19 22:18:11.000000', NULL, 1),
(2240112, 305458, 48245, '<td valign="top">I was in Boston this last week on vacation and we took a day to head up to Salem... took a tour of the Custom house where Mr. Hawthorn says he got his inspiration for the book.</td>', 'I was in Boston this last week on vacation and we took a day to head up to Salem... took a tour of the Custom house where Mr. Hawthorn says he got his inspiration for the book.', '2006-03-19 22:20:55.000000', NULL, 1),
(2240116, 305422, 39057, '<td valign="top">This is a great shot. The expression is perfect. Looks as though she had some acting lessons. I get a feeling in my chest that cries..."what is she looking at" or "what''s out there?"<br/> <br/>10 from me and should be in the top 3.</td>', 'This is a great shot. The expression is perfect. Looks as though she had some acting lessons. I get a feeling in my chest that cries..."what is she looking at" or "what''s out there?" 10 from me and should be in the top 3.', '2006-03-19 22:23:08.000000', NULL, 1),
(2240168, 305418, 34134, '<td valign="top">Creepy! Where''s the Horseman? Beautiful capture. Love the color.</td>', 'Creepy! Where''s the Horseman? Beautiful capture. Love the color.', '2006-03-19 22:50:27.000000', NULL, 1),
(2240170, 305944, 3306, '<td valign="top">Good eye. I like the feeling of this picture.</td>', 'Good eye. I like the feeling of this picture.', '2006-03-19 22:52:50.000000', NULL, 1),
(2240171, 305526, 3306, '<td valign="top">Beautiful sunrise.</td>', 'Beautiful sunrise.', '2006-03-19 22:53:19.000000', NULL, 1),
(2240172, 305914, 3306, '<td valign="top">My favorite story as a child.</td>', 'My favorite story as a child.', '2006-03-19 22:53:42.000000', NULL, 1),
(2240174, 305985, 3306, '<td valign="top">Great rustic feeling to your picture.</td>', 'Great rustic feeling to your picture.', '2006-03-19 22:54:27.000000', NULL, 1),
(2240175, 305891, 3306, '<td valign="top">Your picture truly evokes the feeling of the book you are representing.</td>', 'Your picture truly evokes the feeling of the book you are representing.', '2006-03-19 22:55:33.000000', NULL, 1),
(2240176, 305715, 3306, '<td valign="top">The grass in the forground helps to give depth and interest to your picture. It also helps to break up the monotony of the water.</td>', 'The grass in the forground helps to give depth and interest to your picture. It also helps to break up the monotony of the water.', '2006-03-19 22:56:28.000000', NULL, 1),
(2240178, 305721, 3306, '<td valign="top">Excellent feeling of movement. Well done.</td>', 'Excellent feeling of movement. Well done.', '2006-03-19 22:56:52.000000', NULL, 1),
(2240179, 305741, 3306, '<td valign="top">Good action shot</td>', 'Good action shot', '2006-03-19 22:57:11.000000', NULL, 1),
