(2240184, 304802, 3306, '<td valign="top">This has the potential to be a very good picture. The interest is in the fire not the smoke. I wish you could have gotten a little closer and cropped out some of the sky.</td>', 'This has the potential to be a very good picture. The interest is in the fire not the smoke. I wish you could have gotten a little closer and cropped out some of the sky.', '2006-03-19 22:59:18.000000', NULL, 1),
(2240185, 305967, 3306, '<td valign="top">Well done.</td>', 'Well done.', '2006-03-19 22:59:36.000000', NULL, 1),
(2240190, 305026, 3306, '<td valign="top">The lighting is interesting but I think you could have done more with the composition to make it more creative.</td>', 'The lighting is interesting but I think you could have done more with the composition to make it more creative.', '2006-03-19 23:00:51.000000', NULL, 1),
(2240191, 305910, 3306, '<td valign="top">One of my childrens'' favorite stories, although I could never understand why!</td>', 'One of my childrens'' favorite stories, although I could never understand why!', '2006-03-19 23:01:52.000000', NULL, 1),
(2240197, 305994, 3306, '<td valign="top">Interesting composition and creatively done to make it fit the title.</td>', 'Interesting composition and creatively done to make it fit the title.', '2006-03-19 23:03:44.000000', NULL, 1),
(2240199, 305598, 3306, '<td valign="top">Might have looked better in Black &amp; White.</td>', 'Might have looked better in Black & White.', '2006-03-19 23:04:13.000000', NULL, 1),
(2240200, 305493, 3306, '<td valign="top">Interesting angle.</td>', 'Interesting angle.', '2006-03-19 23:04:56.000000', NULL, 1),
