(2240210, 304688, 33400, '<td valign="top">Really seems to catch the essence of Hemmingway.  Bumping</td>', 'Really seems to catch the essence of Hemmingway.  Bumping', '2006-03-19 23:08:05.000000', NULL, 1),
(2240211, 305422, 3306, '<td valign="top">I like the off center composition.</td>', 'I like the off center composition.', '2006-03-19 23:08:16.000000', NULL, 1),
(2240217, 305985, 33400, '<td valign="top">Don''t know this quote, and can''t put my finger on what I like about this pic, but I really like it.  Bumping up.</td>', 'Don''t know this quote, and can''t put my finger on what I like about this pic, but I really like it.  Bumping up.', '2006-03-19 23:09:36.000000', NULL, 1),
