INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2240220, 305340, 3306, '<td valign="top">Wow, what a neat looking tree. Nicely captured.</td>', 'Wow, what a neat looking tree. Nicely captured.', '2006-03-19 23:10:43.000000', NULL, 1),
(2240221, 305864, 3306, '<td valign="top">He looks hungry.</td>', 'He looks hungry.', '2006-03-19 23:11:11.000000', NULL, 1),
(2240223, 305619, 33400, '<td valign="top">Beautiful imagery.  My only complaint (minor) is that the male angel''s wreath looks a little plastic, and does not seem to belng with the color scheme of this photo.<br/>Still, a great pic.</td>', 'Beautiful imagery.  My only complaint (minor) is that the male angel''s wreath looks a little plastic, and does not seem to belng with the color scheme of this photo.Still, a great pic.', '2006-03-19 23:11:59.000000', NULL, 1),
(2240224, 304792, 3306, '<td valign="top">Beautiful contrast between the blue, white and greys. A real eye catcher.</td>', 'Beautiful contrast between the blue, white and greys. A real eye catcher.', '2006-03-19 23:12:00.000000', NULL, 1),
(2240225, 305619, 3306, '<td valign="top">A beautiful composition.</td>', 'A beautiful composition.', '2006-03-19 23:12:28.000000', NULL, 1),
(2240227, 305911, 3306, '<td valign="top">Beautifully done. One of my favorites</td>', 'Beautifully done. One of my favorites', '2006-03-19 23:12:46.000000', NULL, 1),
(2240228, 305807, 33400, '<td valign="top">Good focus on the moon.  Tree limbs are a little dark for my monitor - hardly your fault though.  Good pic.</td>', 'Good focus on the moon.  Tree limbs are a little dark for my monitor - hardly your fault though.  Good pic.', '2006-03-19 23:12:53.000000', NULL, 1),
(2240232, 305506, 33400, '<td valign="top">Not really depicting any passage from the original.  However, points for effort - you must have taken a long time to adorn your angry grapes.</td>', 'Not really depicting any passage from the original.  However, points for effort - you must have taken a long time to adorn your angry grapes.', '2006-03-19 23:14:53.000000', NULL, 1),
