(2240275, 305456, 48717, '<td valign="top">Yucky to look at, but well rendered tones.</td>', 'Yucky to look at, but well rendered tones.', '2006-03-19 23:35:07.000000', NULL, 1),
(2240311, 305171, 37961, '<td valign="top">Dramatic.</td>', 'Dramatic.', '2006-03-19 23:48:20.000000', NULL, 1),
(2240313, 305382, 37961, '<td valign="top">ladymonarda?<br/> This is excellent. Very moody and dark.</td>', 'ladymonarda? This is excellent. Very moody and dark.', '2006-03-19 23:48:33.000000', NULL, 1),
(2240314, 304906, 37961, '<td valign="top">I really like this. Everything just pops. Wow.</td>', 'I really like this. Everything just pops. Wow.', '2006-03-19 23:48:40.000000', NULL, 1),
