INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2241863, 305619, 18552, '<td valign="top">Congratulations, Gary on Another(!!!) ribbon! Wow, I can''t believe I managed to do a bit better than you to get the Blue - your picture is so professional and almost perfect. I did notice that the guy has his wings on upside down - otherwise; the lighting, the composition, everything is perfect. Someday, I hope my ribbon winning ability is as consistant as yours and doesn''t depend so much on luck but rather on skill as yours does. Wondering what score you were getting really made this challenge interesting and nerve wracking for me as I read in the threads you were doing well enough to replace one of the high scoring pictures on your profile page.</td>', 'Congratulations, Gary on Another(!!!) ribbon! Wow, I can''t believe I managed to do a bit better than you to get the Blue - your picture is so professional and almost perfect. I did notice that the guy has his wings on upside down - otherwise; the lighting, the composition, everything is perfect. Someday, I hope my ribbon winning ability is as consistant as yours and doesn''t depend so much on luck but rather on skill as yours does. Wondering what score you were getting really made this challenge interesting and nerve wracking for me as I read in the threads you were doing well enough to replace one of the high scoring pictures on your profile page.', '2006-03-20 13:48:18.000000', NULL, 0),
(2241864, 304790, 47117, '<td valign="top">I am going to Birmingham this year. We are taking our son to Visionland for a 3 day weekend.  I looked up the Zoo in the area, and I did see this shot.  I knew it looked familiar! LOL...Have you ever gone to the Vulcan Tower?  I am wondering what kind of view you get up there, and if you have taken photos from there.  Please let me know.  You can write to my email, as my PM isn''t working well. But you can PM me if you like.</td>', 'I am going to Birmingham this year. We are taking our son to Visionland for a 3 day weekend.  I looked up the Zoo in the area, and I did see this shot.  I knew it looked familiar! LOL...Have you ever gone to the Vulcan Tower?  I am wondering what kind of view you get up there, and if you have taken photos from there.  Please let me know.  You can write to my email, as my PM isn''t working well. But you can PM me if you like.', '2006-03-20 13:48:37.000000', NULL, 0),
(2241865, 305997, 18552, '<td valign="top">Congratulations on your ribbon, Rudy. This is an amazingly good picture - the composition and lighting is fantastic. I''m really proud to be a ribbon winner in this challenge along with you and Gary.</td>', 'Congratulations on your ribbon, Rudy. This is an amazingly good picture - the composition and lighting is fantastic. I''m really proud to be a ribbon winner in this challenge along with you and Gary.', '2006-03-20 13:52:02.000000', NULL, 0),
(2241870, 305665, 19978, '<td valign="top">Responding to your plea for "negative" comments.<br/> <br/>For me, I just don''t buy that there''s something in the book that is so amazing. Other ideas? A boy looking at his first girly magazine; a film photographer looking at the price of a dSLR; a woman opening a jewelry box, etc., you get the idea. There has to be something that communicates with the viewer that matches the expression of amazement on the guy''s face. For a challenge "literary," I have trouble coming up with a good idea, but that''s my take.</td>', 'Responding to your plea for "negative" comments. For me, I just don''t buy that there''s something in the book that is so amazing. Other ideas? A boy looking at his first girly magazine; a film photographer looking at the price of a dSLR; a woman opening a jewelry box, etc., you get the idea. There has to be something that communicates with the viewer that matches the expression of amazement on the guy''s face. For a challenge "literary," I have trouble coming up with a good idea, but that''s my take.', '2006-03-20 14:01:32.000000', NULL, 0),
(2241879, 305619, 36091, '<td valign="top">Congrats on your ribbon! very nice photo!</td>', 'Congrats on your ribbon! very nice photo!', '2006-03-20 14:10:50.000000', NULL, 0),
(2241880, 304790, 18552, '<td valign="top">I was really glad to read about your picture and find out how rare a creature this is.</td>', 'I was really glad to read about your picture and find out how rare a creature this is.', '2006-03-20 14:10:50.000000', NULL, 0),
(2241883, 305665, 16912, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by strangeghost:</b></div><hr/><i> Responding to your plea for "negative" comments.<br/> <br/>For me, I just don''t buy that there''s something in the book that is so amazing. Other ideas? A boy looking at his first girly magazine; a film photographer looking at the price of a dSLR; a woman opening a jewelry box, etc., you get the idea. There has to be something that communicates with the viewer that matches the expression of amazement on the guy''s face. For a challenge "literary," I have trouble coming up with a good idea, but that''s my take. </i></td></tr></table> <br/> <br/>Now, if I received ''negative'' comments like this I''d be quite happy :) IMHO this isn''t a negative comment its constructive critisism with some very good ideas for improvement :) I still like the shot as is though and am impressed with your dedication to get the setup as you wanted it.<br/><br/><i>Message edited by author 2006-03-20 14:15:27.</i></td>', 'Originally posted by strangeghost: Responding to your plea for "negative" comments. For me, I just don''t buy that there''s something in the book that is so amazing. Other ideas? A boy looking at his first girly magazine; a film photographer looking at the price of a dSLR; a woman opening a jewelry box, etc., you get the idea. There has to be something that communicates with the viewer that matches the expression of amazement on the guy''s face. For a challenge "literary," I have trouble coming up with a good idea, but that''s my take.   Now, if I received ''negative'' comments like this I''d be quite happy :) IMHO this isn''t a negative comment its constructive critisism with some very good ideas for improvement :) I still like the shot as is though and am impressed with your dedication to get the setup as you wanted it.', '2006-03-20 14:13:57.000000', '2006-03-20 14:15:27.000000', 0),
(2241885, 304596, 18552, '<td valign="top">This is so lovely, Bear. So close to a ribbon - I''m shocked how much the score changed at the rollover. Your sunrise/sunset pictures are always hauntingly lovely. I''d love to go on a photo outing with you to see how you set up and then most especially, I''d love to watch you edit your pictures so I could learn some of your outstanding editing skills!</td>', 'This is so lovely, Bear. So close to a ribbon - I''m shocked how much the score changed at the rollover. Your sunrise/sunset pictures are always hauntingly lovely. I''d love to go on a photo outing with you to see how you set up and then most especially, I''d love to watch you edit your pictures so I could learn some of your outstanding editing skills!', '2006-03-20 14:16:14.000000', NULL, 0),
(2241886, 305957, 18552, '<td valign="top">Congratulations on your Top 5 finish. Your picture has such lovely lighting and such a haunting mood.</td>', 'Congratulations on your Top 5 finish. Your picture has such lovely lighting and such a haunting mood.', '2006-03-20 14:18:16.000000', NULL, 0),
